import{_ as r,l as n,o as t,c as s,v as e,p as l,x as i,d as m,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"MiniMax-M1","description":"","frontmatter":{"title":"MiniMax-M1","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/minimax-m1.md","filePath":"llm/minimax-m1.md","lastUpdated":1789023840000}'),g={name:"llm/minimax-m1.md"};function d(M,a,c,P,S,E){const o=n("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="minimax-m1" tabindex="-1">MiniMax-M1 <a class="header-anchor" href="#minimax-m1" aria-label="Permalink to &quot;MiniMax-M1&quot;">​</a></h1><div class="epigraph"><p>混合注意力把测试时计算从二次里解放出来；CISPO 裁的是重要性权重而不是 token 更新，让低概率的反思词继续进梯度。</p><footer>—— MiniMax，MiniMax-M1: Scaling Test-Time Compute Efficiently with Lightning Attention，arXiv:2506.13585</footer></div><p><a href="/llm/minimax-text01">MiniMax-Text-01</a> 已经把 Lightning Attention 与 456B/45.9B MoE 做成可下载基座。<strong>MiniMax-M1</strong> 是在该骨干上续训再大规模 RL 的推理模型：原生 <strong>1M</strong> 上下文，放出 40K 与 80K 两档思维预算。相对 <a href="/llm/deepseek-r1">DeepSeek-R1</a> 与 R1-0528，它要证明的不是又一个 GRPO 检查点，而是<strong>长生成在混合注意力上可训练</strong>，以及一套叫 CISPO 的裁剪改写。本篇按 2506.13585 写续训、算法与沙箱奖励，不重写 Text-01 的 7+1 层表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>推理模型把测试时计算当成缩放轴：生成越长，竞赛与代理任务越好。纯 softmax Transformer 上，前填与 RL rollout 的 FLOPs 随长度二次涨。R1 类模型把思维拉到数万 token 时，墙钟被注意力打穿；再叠软件工程轨迹（仓库级输入），1M 上下文几乎不可训。需要一种已经在基座上验证过的线性核，把 64K–100K 生成的相对 FLOPs 压下来，才谈得上「开源权重里的长思维 RL」。</p><p>第二条缺口是算法。作者在混合架构的 zero-RL 里发现：PPO / <a href="/llm/grpo">GRPO</a> 的 <strong>token 级 clip</strong> 会把「However / Wait / Aha」一类低概率分叉词在第一次 on-policy 更新后裁掉，后续 off-policy 步再也看不到它们。长链的反思依赖这些词；<a href="/llm/dapo">DAPO</a> 把上裁剪抬到 \\(1+\\varepsilon_{\\mathrm{high}}\\)，在他们 16 轮 off-policy 的设置里仍不够。</p><h3 id="开源权重里几乎没有混合注意力的大规模-rl" tabindex="-1">开源权重里几乎没有混合注意力的大规模 RL <a class="header-anchor" href="#开源权重里几乎没有混合注意力的大规模-rl" aria-label="Permalink to &quot;开源权重里几乎没有混合注意力的大规模 RL&quot;">​</a></h3><p>报告称 M1 是当时<strong>首个</strong>开源的大规模混合注意力推理模型。闭源里腾讯混元 T1 用过 Mamba，细节很少。Text-01 证明了榜上能打，没有证明在 RL 的训练/推理核不一致时奖励还能涨。M1 的工程问题因此是双重的：算法要保住探索 token，内核要把训练对数概率与推理对数概率对齐。</p><p><span class="marginnote">「相对 R1 在 100K 生成长度上约 25% FLOPs」是报告的理论曲线，对照对象是当时的 DeepSeek-R1 注意力账，不是 0528 的实测延迟。服务 SLA 仍受 softmax 那 1/8 层与 MoE 通信限制。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>数据与冷启动。</strong> 从 Text-01 继续预训练 <strong>7.5T</strong> token：提高解析召回，<strong>不用合成</strong>抽取自然 QA，语义去重，STEM / 代码 / 书 / 推理约占 <strong>70%</strong>。学习率先 \\(8\\times 10^{-5}\\) 恒定 2.5T，再 5T 衰减到 \\(8\\times 10^{-6}\\)。长窗分四段从 32K 推到 <strong>1M</strong>，避免混合核上过猛拉长导致梯度爆炸。随后 SFT 注入带反思的长链，数学与代码约占 60%，作为 RL 的行为先验。</p><p><strong>CISPO。</strong> 组相对优势仍用 GRPO 的均值–方差；损失改成 token 级（与 DAPO 相同）。不 clip 策略比率本身，而 clip <strong>stop-gradient 后的重要性权重</strong>，再乘 \\(\\hat A\\log\\pi\\)：</p> \\[\\hat r_{i,t}=\\mathrm{clip}\\bigl(r_{i,t}(\\theta),\\,1-\\varepsilon^{\\mathrm{IS}}_{\\mathrm{low}},\\,1+\\varepsilon^{\\mathrm{IS}}_{\\mathrm{high}}\\bigr),\\qquad \\mathcal{J}_{\\mathrm{CISPO}}\\propto \\sum_{i,t}\\mathrm{sg}(\\hat r_{i,t})\\,\\hat A_{i,t}\\log\\pi_\\theta(o_{i,t}\\mid \\cdot). \\]<p>实验里下界放得很宽，主要调 \\(\\varepsilon^{\\mathrm{IS}}_{\\mathrm{high}}\\)。不加 KL。沿用 DAPO 的动态采样与超长惩罚。在 Qwen2.5-32B 的对照上，CISPO 达到 DAPO 同水平约只需一半步数。</p><p><strong>混合核上的 RL 修补。</strong> 训练核与推理核的 token 概率一度错开（相关约 0.9x），奖励不涨；把 LM head 提到 <strong>FP32</strong> 后相关到约 0.99。AdamW 因梯度跨 \\(10^{-18}\\)–\\(10^{-5}\\) 且相邻步弱相关，改为 \\(\\beta_2=0.95\\)、\\(\\epsilon=10^{-15}\\)（默认 VeRL 的 \\(10^{-8}\\) 会不收敛）。若连续 3000 个 token 概率都 \\(\\gt 0.99\\)，提前截断，打断重复环。</p><h3 id="可验证环境与-40k→80k" tabindex="-1">可验证环境与 40K→80K <a class="header-anchor" href="#可验证环境与-40k→80k" aria-label="Permalink to &quot;可验证环境与 40K→80K&quot;">​</a></h3><p>可验证域：竞赛数学约 50K（pass@10 严格在 \\((0,0.9)\\)）、SynLogic 合成的 41 类逻辑约 53K、竞赛编程约 30K，以及从 GitHub issue/PR 搭的 SWE 沙箱（测试执行当奖励）。不可验证域约 25K，用生成式奖励模型；对长链的长度偏置做在线监测，避免 GenRM 奖励冗长。课程：先规则奖励，再混入通用任务。</p><p>40K 跑通后，用该策略筛更难题，分阶段把生成窗扩到 48K … <strong>80K</strong>。后期负样本先顶满窗口，token-level 损失会在后半段堆过大负梯度；对策是重复检测、样本级与 token 级损失并用、降低梯度裁剪与 \\(\\varepsilon^{\\mathrm{IS}}_{\\mathrm{high}}\\)。完整 RL：512×H800、约三周、租卡约 <strong>53.47 万美元</strong>。权重在 GitHub / Hugging Face，vLLM 与 Transformers 可跑。</p>',18)),(t(),l(h,null,{default:i(()=>[p(o,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20T01%5B%22Text-01%20456B%2F45.9B%22%5D%20--%3E%20CPT%5B%22%E7%BB%AD%E8%AE%AD%207.5T%20%2B%20%E9%95%BF%E7%AA%97%E8%87%B3%201M%22%5D%0A%20%20CPT%20--%3E%20SFT%5B%22%E9%95%BF%E9%93%BE%20SFT%22%5D%0A%20%20SFT%20--%3E%20RL%5B%22CISPO%EF%BC%9Aclip%20IS%20%E6%9D%83%E9%87%8D%22%5D%0A%20%20RL%20--%3E%20M40%5B%22M1-40k%22%5D%0A%20%20M40%20--%3E%20M80%5B%22%E5%88%86%E9%98%B6%E6%AE%B5%E5%88%B0%2080k%22%5D%0A%20%20ENV%5B%22%E6%95%B0%E5%AD%A6%20%2F%20SynLogic%20%2F%20%E4%BB%A3%E7%A0%81%20%2F%20SWE%20%E6%B2%99%E7%AE%B1%22%5D%20--%3E%20RL%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Lightning 层把通道混合做成对长度近线性，softmax 层保留针检索。RL 的 rollout 是长度税最高的一段，线性核直接变成<strong>可负担的测试时缩放</strong>。CISPO 的机制相反：PPO clip 在比率过大时把该 token 的梯度<strong>丢掉</strong>；把 clip 移到 IS 权重上，低概率分叉词仍贡献 \\(\\log\\pi\\) 梯度，只是权重被截断，熵不至于塌成「只会说稳妥词」。这与 DAPO 的 Clip-Higher 同病：都在救探索，但 CISPO 不依赖「放宽上剪仍可能被 clip 掉」。</p><p><span class="marginnote">报告对照表把 DS-R1 写成 R1-0528 的输入 128K / 输出 64K，M1-80k 为输入 1M / 输出 80K。比的是窗口产品规格，不是同一套评测 harness 下的 FLOPs 实测。</span></p><h3 id="沙箱奖励把「推理」从竞赛里拉出来" tabindex="-1">沙箱奖励把「推理」从竞赛里拉出来 <a class="header-anchor" href="#沙箱奖励把「推理」从竞赛里拉出来" aria-label="Permalink to &quot;沙箱奖励把「推理」从竞赛里拉出来&quot;">​</a></h3><p>数学与 Codeforces 仍是规则核对；SWE 环境用真实测试失败/通过，迫使策略学习定位、补丁与回归，而不是只写竞赛函数。这是相对 R1 公开叙述最清楚的任务差分。GenRM 段承认长度黑客：离线对抗不够，必须在 RL 过程中看策略是否靠变长刷分。课程先可验证后开放，避免写作 RM 过早污染数学探索。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>数学与 LiveCodeBench 上 M1-80k 低于 R1-0528（报告表：AIME 2025 76.9 vs 87.5；LiveCodeBench 65.0 vs 73.1），强项在 SWE-bench Verified（约 56 vs Qwen3-235B 的 34.4）、工具（TAU-Bench）与长上下文（OpenAI-MRCR 128k / 1M）。不要用「开源推理 SOTA」一句话抹平这张表。40k 是 80k 训练的中间相，不是另套数据。</p><p>混合核的训练/推理不一致是真实失败模式：小稠密 softmax 模型上可能看不到，M1 上会让奖励曲线假死。复现 CISPO 却仍用 PPO clip，救不了他们记录的分叉词问题。SynLogic 在 80K 阶段要降采样，否则重复模式会毁长窗 RL。</p><p><span class="marginnote">CISPO 因 clip IS 权重，梯度相对无偏 REINFORCE <strong>略有偏</strong>。作者接受这笔偏差，换「所有 token 都在」。不要把它写成对 GRPO 的无偏修正——那是 <a href="/llm/dr-grpo">Dr. GRPO</a> 的叙事。</span></p><h3 id="何时不必上-m1" tabindex="-1">何时不必上 M1 <a class="header-anchor" href="#何时不必上-m1" aria-label="Permalink to &quot;何时不必上 M1&quot;">​</a></h3><p>短上下文聊天、没有 1M 输入，混合注意力的服务栈成本可能高于纯 Transformer 生态。只要竞赛数学、要 0528 的 AIME，选错检查点。没有 SWE 沙箱却想「复现 M1」，只能复现 CISPO 的数学消融，复现不了软件工程那段奖励。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>M1 在 Text-01 的 Lightning + MoE 上续训 7.5T，再 CISPO RL；原生 1M 输入，放出 40K / 80K 思维档。</li><li>CISPO 裁重要性权重、保留全部 token 梯度；对照 Qwen2.5-32B 上相对 DAPO 约 2× 步数效率。</li><li>混合核 RL 要修 LM head 精度、Adam \\(\\epsilon\\) 与重复截断，否则奖励不涨。</li><li>数据含数学、41 类逻辑、竞赛代码与 SWE 执行奖励；长窗阶段需降采样合成逻辑。</li><li>竞赛弱于 R1-0528，长上下文与工具更强；完整 RL 约 512×H800 三周。</li><li>出处：MiniMax，<em>MiniMax-M1</em>，arXiv:2506.13585；基座见 <em>MiniMax-01</em>，arXiv:2501.08313。</li></ul>',13))])}const A=r(g,[["render",d]]);export{_ as __pageData,A as default};
